// Query: *[_id == $id && kind == "use"][0] {    _id,    _updatedAt,    code,    "titoli": title,    "intro": intro[$locale],    "body": body[$locale][]{      ...,      markDefs[]{        ...,        _type == "internalLink" => { "slug": reference->slug.current }      },      _type == "figure" => { image { ..., "metadata": asset->metadata { dimensions } } },      _type == "figurePair" => {        left { ..., "metadata": asset->metadata { dimensions } },        right { ..., "metadata": asset->metadata { dimensions } }      }    },    seo {      metaTitle,      metaDescription,      noIndex,      ogImage { ..., "metadata": asset->metadata }    },    "inEvidenza": collections[]._ref,    "collections": *[      _type == "collection" && (!defined(language) || language == "it") && (        _id in ^.collections[]._ref ||        count(*[          _type == "model" && references(^._id) &&          productSubtype in ["colonna", "colonna-divisibile"] &&          count(description.it) > 0 &&          !string::startsWith(lower(pt::text(description.it)), "colonna per lavabo") &&          !string::startsWith(lower(pt::text(description.it)), "colonna per vasca")        ]) > 0      )    ] | order(order asc) {      _id,      code,      title,      "slug": slug.current,      tagline,      isCustomizable,      featured,      "articleCount": count(*[_type=="model" && references(^._id)]),      "finishCount": count(array::unique(*[_type=="model" && references(^._id)].availableFinishes[]._ref)),      "productMacros": array::unique(*[_type=="model" && references(^._id)].productMacro),      coverImage {        ...,        "metadata": asset->metadata      }    }  }
